/* JAH demo program — JAH-NFEATS-000001 */
/* Starfield Navigation */
/* RUN ON PC: save as demo.js, then run: node demo.js */
console.log("MINIATURE CORE — Starfield Navigation: inverted index");
var docs=["the archive index maps terms to record ids","chunks hold one hundred records each","the manifest lists every database","search scans the index then ranks hits"];
var idx={};
docs.forEach(function(d,i){d.split(" ").forEach(function(w){(idx[w]=idx[w]||[]).push(i);});});
var q="stars";
console.log("query: "+q);
console.log("hits: "+JSON.stringify(idx[q]||[]));
console.log("terms indexed: "+Object.keys(idx).length);

/* JAH demo program — JAH-NFEATS-000002 */
/* Dream Playback */
/* RUN ON PC: save as demo.js, then run: node demo.js */
console.log("MINIATURE CORE — Dream Playback: deterministic seed replay");
function rng(a){return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var r=rng(2),vals=[];
for(var i=0;i<5;i++)vals.push(r().toFixed(6));
console.log("seed 2 -> "+vals.join(", "));
console.log("replay identical: "+(vals.join(",")===vals.join(",")));

/* JAH demo program — JAH-NFEATS-000003 */
/* Whisper Export */
/* RUN ON PC: save as demo.js, then run: node demo.js */
console.log("MINIATURE CORE — Whisper Export: run-length compression");
var s="";for(var i=0;i<14;i++)s+="AB";s+="XYZ";for(var j=0;j<9;j++)s+="Q";
var out="",k=0;
while(k<s.length){var c=s[k],n=1;while(s[k+n]===c)n++;out+=c+n;k+=n;}
console.log("raw bytes: "+s.length);
console.log("encoded bytes: "+out.length);
console.log("ratio: "+(out.length/s.length).toFixed(3));

/* JAH demo program — JAH-NFEATS-000004 */
/* Soul Emblems */
/* RUN ON PC: save as demo.js, then run: node demo.js */
console.log("MINIATURE CORE — Soul Emblems: FNV-1a verification");
function fnv(s){var h=0x811c9dc5;for(var i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,0x01000193);}return (h>>>0).toString(16);}
["record-alpha","record-beta","record-alpha"].forEach(function(s){console.log(s+" -> "+fnv(s));});
console.log("integrity check: "+(fnv("record-alpha")===fnv("record-alpha")?"PASS":"FAIL"));

/* JAH demo program — JAH-NFEATS-000005 */
/* Guardian Filing */
/* RUN ON PC: save as demo.js, then run: node demo.js */
console.log("MINIATURE CORE — Guardian Filing: duplicate detection");
var ids=["JAH-A-0001","JAH-A-0002","JAH-A-0001","JAH-A-0003","JAH-A-0002","JAH-A-0004"];
var seen={},dups=[];
ids.forEach(function(id){if(seen[id]){if(dups.indexOf(id)<0)dups.push(id);}else seen[id]=1;});
console.log("scanned: "+ids.length+" ids");
console.log("duplicates: "+JSON.stringify(dups));
console.log("unique: "+Object.keys(seen).length);

